export function solve(input) {
  const counts = {};
  for (const s of input) counts[s] = (counts[s] || 0) + 1;
  return Object.keys(counts).sort((a, b) => {
    const diff = counts[b] - counts[a];
    if (diff !== 0) return diff;
    return a < b ? -1 : a > b ? 1 : 0;
  });
}

